begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,other_property uuid,actor uuid,review_id uuid,other_review uuid,case_id uuid,ticket_id uuid);
insert into fixture values(gen_random_uuid(),gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid(),gen_random_uuid(),null,null);
insert into public.properties(id,org_id,name)select property_id,'22222222-2222-2222-2222-222222222222'::uuid,'ReviewFlow case rollback fixture' from fixture union all select other_property,'22222222-2222-2222-2222-222222222222'::uuid,'ReviewFlow case rollback fixture' from fixture;
insert into public.reviews(id,property_id,platform,review_text,rating) select review_id,property_id,'other','Maintenance follow-up is needed.',2 from fixture union all select other_review,other_property,'other','Another property review.',3 from fixture;
create function pg_temp.input(action text,extra jsonb default '{}') returns jsonb language plpgsql as $$declare f fixture;c public.reputation_cases;s integer;begin select * into f from fixture;select * into c from public.reputation_cases where review_id=f.review_id;select source_version into s from public.reviews where id=f.review_id;return jsonb_build_object('action',action,'reviewId',f.review_id,'sourceVersion',s,'reason','Fixture operator reviewed the evidence')||case when c.id is null then '{}'::jsonb else jsonb_build_object('caseId',c.id,'expectedVersion',c.version) end||extra;end$$;
create function pg_temp.decide(action text,extra jsonb default '{}') returns jsonb language plpgsql as $$declare f fixture;begin select * into f from fixture;return public.decide_reviewflow_case(gen_random_uuid(),f.property_id,f.actor,pg_temp.input(action,extra));end$$;
do $$declare f fixture;r jsonb;command_id uuid:=gen_random_uuid();payload jsonb;begin select * into f from fixture;
 perform pg_temp.check(not has_function_privilege('authenticated','public.decide_reviewflow_case(uuid,uuid,uuid,jsonb)','execute') and not has_table_privilege('authenticated','public.review_tickets','update'),'browser cannot bypass atomic staff decisions');
 perform pg_temp.check(public.decide_reviewflow_case(command_id,f.property_id,gen_random_uuid(),pg_temp.input('create'))->>'state'='forbidden','unknown actor cannot open case');
 perform pg_temp.check(pg_temp.decide('create',jsonb_build_object('reviewId',f.other_review))->>'state'='not_found','case creation cannot cross property source scope');
 perform pg_temp.check(pg_temp.decide('create','{"sourceVersion":99}')->>'state'='stale_source','case creation checks exact current source');
 payload:=pg_temp.input('create');r:=public.decide_reviewflow_case(command_id,f.property_id,f.actor,payload);update fixture set case_id=(r->>'caseId')::uuid;
 perform pg_temp.check(r->>'state'='saved' and(r->>'caseVersion')::integer=1,'opening case saves a real version');
 perform pg_temp.check(public.decide_reviewflow_case(command_id,f.property_id,f.actor,payload)->>'state'='replayed','lost creation reply cannot duplicate the case');
 perform pg_temp.check(public.decide_reviewflow_case(command_id,f.property_id,f.actor,payload||'{"reason":"different decision"}')->>'state'='request_conflict','saved decision payload cannot be replaced');
 perform pg_temp.check(pg_temp.decide('create')->>'state'='case_exists','second case request returns current-case conflict');
 perform pg_temp.check((select count(*)=1 from public.reputation_cases where review_id=f.review_id) and(select count(*)=1 from public.shared_action_events where property_id=f.property_id and action='review.case.created'),'case and creation activity exist exactly once');
end$$;
do $$declare f fixture;r jsonb;payload jsonb;begin select * into f from fixture;
 perform pg_temp.check(pg_temp.decide('update',jsonb_build_object('ownerId',gen_random_uuid()))->>'state'='assignee_unavailable','a foreign or missing assignee cannot receive work');
 payload:=pg_temp.input('update',jsonb_build_object('ownerId',f.actor,'priority','urgent','status','remediation','remediationState','in_progress','slaDueAt','2026-10-01T12:00:00Z'));
 r:=public.decide_reviewflow_case(gen_random_uuid(),f.property_id,f.actor,payload);perform pg_temp.check(r->>'state'='saved','owner, priority, deadline and remediation save together');
 perform pg_temp.check(public.decide_reviewflow_case(gen_random_uuid(),f.property_id,f.actor,payload)->>'state'='stale_case','a stale tab cannot replace new case decisions');
 perform pg_temp.check((select owner_profile_id=f.actor and priority='urgent' and status='remediation' and remediation_state='in_progress' and sla_due_at='2026-10-01T12:00:00Z'::timestamptz from public.reputation_cases where id=f.case_id),'case state matches the reviewed values');
 begin perform pg_temp.decide('update','{"status":"ready_to_post"}');raise exception 'FAIL bypass approval';exception when raise_exception then if SQLERRM<>'Response approval and closure require their own reviewed decisions' then raise;end if;end;
 perform pg_temp.check(true,'case control cannot grant public-response approval');
 r:=pg_temp.decide('ticket.create',jsonb_build_object('title','Repair follow-up','description','Inspect source evidence','priority','high','ownerId',f.actor));update fixture set ticket_id=(r->>'ticketId')::uuid;
 perform pg_temp.check(r->>'state'='saved' and(r->>'ticketVersion')::integer=1,'staff ticket is created through the recorded case');
 perform pg_temp.check(pg_temp.decide('resolve','{"resolutionNotes":"Staff confirmed repairs"}')->>'state'='open_tickets','case cannot conceal unfinished staff tickets');
end$$;
do $$declare f fixture;r jsonb;payload jsonb;command_id uuid:=gen_random_uuid();begin select * into f from fixture;
 perform pg_temp.check(pg_temp.decide('ticket.update',jsonb_build_object('ticketId',f.ticket_id,'expectedTicketVersion',99,'status','resolved','resolutionNotes','Repair verified'))->>'state'='stale_ticket','ticket updates require their exact version');
 begin perform pg_temp.decide('ticket.update',jsonb_build_object('ticketId',f.ticket_id,'expectedTicketVersion',1,'status','resolved'));raise exception 'FAIL missing resolution';exception when raise_exception then if SQLERRM<>'Record ticket resolution evidence' then raise;end if;end;
 perform pg_temp.check(true,'ticket cannot close without actual resolution evidence');
 payload:=pg_temp.input('ticket.update',jsonb_build_object('ticketId',f.ticket_id,'expectedTicketVersion',1,'status','resolved','resolutionNotes','Repair verified by staff','title','Repair verified','description','Saved follow-up evidence','ownerId',null));
 r:=public.decide_reviewflow_case(command_id,f.property_id,f.actor,payload);
 perform pg_temp.check(r->>'state'='saved' and public.decide_reviewflow_case(command_id,f.property_id,f.actor,payload)->>'state'='replayed','ticket completion and lost-response replay share one identity');
 perform pg_temp.check((select status='resolved' and resolved_at is not null and assigned_to is null and version=2 from public.review_tickets where id=f.ticket_id),'ticket uses real schema fields and clears its owner explicitly');
 perform pg_temp.check((select reputation_case_events.payload->'ticketBefore'->>'title'='Repair follow-up' and reputation_case_events.payload->'ticketAfter'->>'title'='Repair verified' from public.reputation_case_events where case_id=f.case_id and event_type='ticket.updated' limit 1),'private case history preserves exact ticket revisions');
 perform pg_temp.check(pg_temp.decide('ticket.update',jsonb_build_object('ticketId',f.ticket_id,'expectedTicketVersion',2,'status','open'))->>'state'='ticket_closed','ordinary edits cannot silently reopen resolved tickets');
 perform pg_temp.check(pg_temp.decide('resolve','{"resolutionNotes":"All follow-up verified by staff"}')->>'state'='saved','case can resolve after its staff work is complete');
 perform pg_temp.check((select status='resolved' and remediation_state='completed' from public.reputation_cases where id=f.case_id),'resolution updates case and remediation together');
 perform pg_temp.check(pg_temp.decide('ticket.reopen',jsonb_build_object('ticketId',f.ticket_id,'expectedTicketVersion',2))->>'state'='case_closed','ticket cannot reopen underneath a closed case');
 perform pg_temp.check(pg_temp.decide('note','{"note":"Resident confirmation is still separate."}')->>'state'='saved','closed cases still accept attributed follow-up notes');
 perform pg_temp.check(pg_temp.decide('reopen')->>'state'='saved','explicit reopening records recurrence');
 perform pg_temp.check((select status='triaged' and reopened_count=1 and resolved_at is null and resolution_notes is null from public.reputation_cases where id=f.case_id),'reopening clears current closure but retains its event evidence');
 perform pg_temp.check(pg_temp.decide('ticket.reopen',jsonb_build_object('ticketId',f.ticket_id,'expectedTicketVersion',2))->>'state'='saved','ticket reopens only after the case is open');
 perform pg_temp.check((select status='open' and resolved_at is null and resolution_notes is null from public.review_tickets where id=f.ticket_id),'reopened ticket does not carry a false current completion');
 perform pg_temp.check(not exists(select 1 from public.shared_action_events where property_id=f.property_id and row_to_json(shared_action_events)::text like '%Repair verified by staff%'),'free-text evidence is private rather than in the general activity stream');
end$$;
create function pg_temp.fail_case_history() returns trigger language plpgsql as $$begin if new.action='review.case.note_added' then raise exception 'Fixture case history failure';end if;return new;end$$;
create trigger case_fixture_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_case_history();
do $$declare f fixture;v integer;n bigint;begin select * into f from fixture;select version into v from public.reputation_cases where id=f.case_id;select count(*) into n from public.reputation_case_events where case_id=f.case_id;
 begin perform pg_temp.decide('note','{"note":"This must roll back"}');raise exception 'FAIL event failure ignored';exception when raise_exception then if SQLERRM<>'Fixture case history failure' then raise;end if;end;
 perform pg_temp.check((select version=v from public.reputation_cases where id=f.case_id) and(select count(*)=n from public.reputation_case_events where case_id=f.case_id),'case, private evidence and shared action fail atomically');
end$$;
drop trigger case_fixture_failure on public.shared_action_events;
do $$declare f fixture;begin select * into f from fixture;
 begin delete from public.review_tickets where id=f.ticket_id;raise exception 'FAIL ticket deleted';exception when raise_exception then if SQLERRM<>'Case and ticket history must be retained' then raise;end if;end;
 perform pg_temp.check(true,'staff ticket history cannot be deleted');
 begin update public.reputation_case_events set payload='{}' where case_id=f.case_id;raise exception 'FAIL timeline edited';exception when raise_exception then if SQLERRM<>'Review evidence is immutable' then raise;end if;end;
 perform pg_temp.check(true,'case timeline is append only');
 begin update public.review_tickets set property_id=f.other_property where id=f.ticket_id;raise exception 'FAIL identity moved';exception when raise_exception then if SQLERRM<>'Case and ticket identity cannot change' then raise;end if;end;
 perform pg_temp.check(true,'ticket source scope is immutable');
end$$;
select count(*) as passed_assertions from checks;
rollback;
